(* [comment removed for export] *)
Definition c_w (A : astate) (ws : list fct) : ctx_rec := fun k =>
  match k with
  | KBounce _ | KUseq _ | KSeq => match wlook ws (caddr k) with Some b => b | None => a_ctx A k end
  | _ => a_ctx A k
  end.

